fn solve(a: i8, b: i8, f: i8, k: i8) -> i8 {
    // Use wider ints internally to avoid overflow in expressions like 2*a - f.
    let a = a as i32;
    let b = b as i32;
    let f = f as i32;
    let k = k as i32;

    // Distances from station to each endpoint
    let to_station = f;         // from start endpoint
    let to_far = a - f;         // from the other endpoint

    // Basic reachability constraints (station must be reachable from both sides)
    if b < to_station || b < to_far {
        return -1;
    }

    if k == 1 {
        // Single journey: possible if either direct (b >= a) or via station (b >= f).
        // Since b >= f already holds here, infeasible only if b < a and b < f,
        // but b < f can't happen due to the earlier check.
        if b >= a {
            return 0; // no refuel needed
        } else {
            return 1; // must refuel once at station
        }
    }

    // Multiple journeys: extra constraint as stated
    let needed = 2 * a - f;
    if b < needed {
        return -1;
    }

    // Feasible and with >1 journeys: at least one refuel will be needed at some point.
    1
}